・型枠・支保工の存置期間と脱型時の温度差の管理
・凍結した地盤や型枠、雪氷の上には絶対に打ち込まない★
・気象予報を毎日確認し、寒波が来る場合は打込みを中止する判断基準を決めておく

【図解】寒中で禁止される行為
　行為｜可否｜理由
　凍結地盤の上に打込む｜×｜融解時に沈下しひび割れる
