・シートを段階的に外す、ヒータ温度を徐々に下げるなど、緩やかに外気温になじませる
・部材内外の温度差は20℃以内に収めるのが一般的な目安★
・脱型後も凍結融解を受ける環境なら、シート覆い等を継続する

