・「暑中は長期強度が高くなる」→×。低くなる★
・「暑中は空気量が増加しやすい」→×。減少しやすい★
・「スランプ低下は現場で加水して調整する」→×
・「促進形混和剤を用いる」→×。遅延形を用いる★
・寒中の4℃と暑中の25℃の入れ替えは最頻出

★ここだけ暗記
