        id: 'cc-ka-10',
        title: '断熱温度上昇と発熱特性',
        emoji: '📈',
        body: `▼ゼロから：魔法瓶にお湯を入れると、熱が逃げないのでいつまでも熱いままです。コンクリートの中心部も、周りをコンクリートに囲まれているので熱が逃げにくく、まるで魔法瓶の中にいるような状態になります。この「熱がまったく逃げないと仮定したときの温度上昇」を断熱温度上昇といいます。実際の部材の温度は必ずこれより低くなりますが、発熱の大きさを比べる物差しとして使われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 断熱温度上昇の定義と式
━━━━━━━━━━━━━━━━━━━━━━
・外部と熱のやりとりがない条件（断熱条件）でのコンクリートの温度上昇を断熱温度上昇という★
・断熱温度上昇試験装置で測定し、材齢と温度上昇量の関係を得る
・実用式：Q（t）＝Q無限大×｛1－eの（マイナスγ×t）乗｝
・Q無限大は最終断熱温度上昇量℃、γは温度上昇速度を表す係数（1／日）、tは材齢日★
・より精度の高い式として、Q（t）＝Q無限大×｛1－eの（マイナスγ×（t－t0）のs乗）乗｝も用いられる
・→ Q無限大が「どこまで上がるか」、γが「どれだけ速く上がるか」★

【図解】発熱式のパラメータの意味
　記号｜意味｜大きいと
　Q無限大｜最終断熱温度上昇量★｜到達温度が高くなる
　γ｜温度上昇速度係数★｜早くピークに達する
　t｜材齢（日）｜時間が経つほどQに近づく
　⇒ Q無限大は高さ、γは立ち上がりの速さを決める
　⚠ γが大きいことは総発熱量が大きいことを意味しない。速さと大きさは別物

━━━━━━━━━━━━━━━━━━━━━━
🔑 数値計算例
━━━━━━━━━━━━━━━━━━━━━━
・例題：Q無限大＝50℃、γ＝0.35（1／日）のコンクリートで、材齢3日の断熱温度上昇量を求める
・γ×t＝0.35×3＝1.05
・eの（マイナス1.05）乗＝0.350
・1－0.350＝0.650
・Q（3）＝50×0.650＝32.5℃★
・→ 材齢3日で最終値の65パーセントまで上がる
・例題の続き：材齢7日では
・0.35×7＝2.45
・eの（マイナス2.45）乗＝0.086
・1－0.086＝0.914
・Q（7）＝50×0.914＝45.7℃★
・→ 7日で最終値の91パーセントに達する。発熱の大半は最初の1週間で起こる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 発熱に影響する要因
━━━━━━━━━━━━━━━━━━━━━━
・単位セメント量が大きいほどQ無限大が大きい★。最も影響の大きい要因である
・セメントの種類：早強＞普通＞中庸熱＞低熱＞高炉B種の順に発熱が大きい★
・打込み温度が高いほどγが大きくなり、ピークが早く高くなる★
・粉末度（比表面積）が大きいほど初期の発熱速度が大きい
・混和材（フライアッシュ、高炉スラグ微粉末）の置換で発熱を抑制できる★
・粗骨材の種類（熱物性）も部材温度に影響するが、断熱温度上昇そのものへの影響は小さい
・→ 発熱を抑える最短の道は「単位セメント量を減らす」★

【図解】セメント種類と発熱の大小
　セメント｜発熱の大小｜マスコンでの適否
　早強ポルトランド｜大きい｜×不適
　普通ポルトランド｜中程度｜条件により可
　中庸熱・低熱ポルトランド｜小さい★｜○適する
　高炉セメントB種｜小さい★｜○適する
　⇒ 中庸熱・低熱・高炉B種がマスコンの定番
　⚠ 早強セメントは寒中には有利だがマスコンには不適。適材適所を混同しない

━━━━━━━━━━━━━━━━━━━━━━
🔑 部材の実際の温度との関係
━━━━━━━━━━━━━━━━━━━━━━
・実際の部材中心温度＝打込み温度＋実温度上昇量となる
・実温度上昇量は放熱があるため断熱温度上昇量より小さい★
・部材が厚いほど放熱しにくく、断熱温度上昇量に近づく★
・薄い部材では放熱が大きく、温度上昇はごくわずかになる
・打込み温度が高いと、部材の最高温度もそのぶん高くなる★
・→ 最高温度を下げるには「発熱量を減らす」と「打込み温度を下げる」の二本立て★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・Q（t）＝Q無限大×｛1－eの（マイナスγt）乗｝の式に数値を代入させる計算問題が出る★
・「実際の部材の温度上昇は断熱温度上昇より大きい」→×。小さい★
・「早強セメントはマスコンに適する」→×
・「γが大きいほど最終温度上昇量が大きい」→×。速度の指標である
・「単位セメント量を増やしても発熱は変わらない」→×

★ここだけ暗記
・Q（t）＝Q無限大×｛1－eの（マイナスγt）乗｝★
・Q無限大は到達高さ、γは速さ★
・発熱の主因は単位セメント量★
・実部材の温度上昇は断熱温度上昇より小さい★`,
