        emoji: '📐',
        body: `▼ゼロから：橋げたが壊れるかどうかを判断するとき、「かかる力」と「耐えられる力」を比べます。温度ひび割れも同じで、温度変化で生じる引張応力と、コンクリートが耐えられる引張強度を比べればよいのです。その比が温度ひび割れ指数です。比が1より大きければ理屈のうえでは割れませんが、ばらつきがあるので余裕をみて1.85などの目標値を設定します。数値の意味を理解すれば暗記も楽になります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 温度ひび割れ指数の定義
━━━━━━━━━━━━━━━━━━━━━━
・温度ひび割れ指数Icrは、コンクリートの引張強度を温度応力で除した値である★
・式：Icr＝ft（t）÷σt（t）
・ft（t）は材齢tにおけるコンクリートの引張強度、σt（t）は同材齢の温度による引張応力★
・分子が強度、分母が応力という順序を絶対に取り違えない★
・Icrが大きいほどひび割れにくい★
・材齢ごとに計算し、最小となる値をその部材の温度ひび割れ指数とする★
・→ 「強度÷応力」で大きいほど安全、と覚える★

【図解】温度ひび割れ指数の構成
　要素｜記号｜大きくすると
　分子（引張強度）｜ft｜指数が大きくなり安全側
　分母（温度応力）｜σt｜指数が小さくなり危険側
　指数｜Icr｜大きいほどひび割れにくい★
　⇒ 発熱を抑えて分母を小さくするのが基本戦略
　⚠ 「応力÷強度」と逆に覚えると、大小の判断がすべて反対になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 目標値と発生確率
━━━━━━━━━━━━━━━━━━━━━━
・ひび割れを防止したい場合：Icr 1.85以上★
・ひび割れの発生をできるだけ制限したい場合：Icr 1.2以上1.85未満★
・有害なひび割れの発生を制限したい場合：Icr 0.7以上1.2未満★
・指数が小さいほどひび割れ発生確率は高くなる。指数1.0でおおむね50パーセント程度とされる
・要求性能（水密性、鋼材防食）に応じて目標値を選ぶ★
・→ 1.85・1.2・0.7の三段階を順に暗記する★

【図解】温度ひび割れ指数の目標値
　目的｜指数の目標｜想定される状態
　ひび割れを防止｜1.85以上★｜ほとんど発生しない
　発生を制限｜1.2以上1.85未満★｜幅の小さいものに限定
　有害なものを制限｜0.7以上1.2未満★｜発生は許容し幅を制御
　⇒ 水密性を要する構造物ほど高い目標値を設定する
　⚠ 「1.85以下でひび割れ防止」は不等号の向きが逆。以上である

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算例
━━━━━━━━━━━━━━━━━━━━━━
・例題：材齢7日で引張強度2.40N／mm2、温度応力1.60N／mm2のとき
・Icr＝2.40÷1.60＝1.50★
・→ 1.2以上1.85未満なので「ひび割れの発生をできるだけ制限したい場合」の水準を満たす
・例題：同じ部材で材齢14日に引張強度2.80N／mm2、温度応力2.40N／mm2となったとき
・Icr＝2.80÷2.40＝1.17★
・→ 材齢14日の方が指数が小さい。部材の温度ひび割れ指数は最小値の1.17を採用する★
・例題：目標を1.85とするには、材齢14日の応力をいくらまで下げる必要があるか
・必要応力＝2.80÷1.85＝1.51N／mm2★
・→ 応力を2.40から1.51まで、約37パーセント低減する対策が必要と分かる

━━━━━━━━━━━━━━━━━━━━━━
🔑 指数を大きくする方法
━━━━━━━━━━━━━━━━━━━━━━
・分母を小さくする対策：単位セメント量の低減、低発熱型セメントの使用、打込み温度の低下、パイプクーリング、リフト割りの調整★
・分子を大きくする対策：強度発現の速いセメント、養生の適正化。ただし発熱も増えるため両立が難しい★
・拘束度を下げる：ブロック割り、打継ぎ位置の工夫、緩衝材の設置
・膨張材の使用により、収縮を打ち消す方向のひずみを与える★
・鉄筋量を増やしてもひび割れ発生自体は防げないが、幅を小さく分散できる★
・→ 主戦場は「分母を下げる」側である★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「Icr＝温度応力÷引張強度」→×。逆である★
・「Icrが小さいほどひび割れにくい」→×。大きいほどひび割れにくい★
・「ひび割れ防止の目標は1.2以上」→×。1.85以上★
・「複数材齢の最大値を採用する」→×。最小値を採用する★
・「鉄筋を増やせば温度ひび割れは発生しない」→×。幅を制御できるだけ
・計算問題は割り算一回だが、目標値との照合まで問われる

★ここだけ暗記
・Icr＝引張強度÷温度応力★
・1.85以上で防止、1.2以上で発生制限、0.7以上で有害なものを制限★
・採用するのは材齢ごとの最小値★
・大きいほど安全★`,
