・「通水温度は低いほどよい」→×。温度差20℃程度以内★
・「冷却管は通水後そのまま放置してよい」→×。充填する★
・「プレクーリングは骨材より水を冷やす方が効果的」→×
・「温度降下期は早く冷やすほどよい」→×。徐冷する★

