・「収縮補償の標準使用量は60kg／m3」→×。30kg／m3程度★
・「膨張材使用時は湿潤養生を短くしてよい」→×。むしろ長く★
・「膨張材の膨張はアルカリシリカ反応と同じ機構である」→×
・「使用量は多いほど効果が高い」→×。過膨張は有害★

★ここだけ暗記
・系統はエトリンガイト系・石灰系・複合系★
・収縮補償は30kg／m3程度、ケミカルプレストレスは40から60kg／m3★
