        emoji: '💎',
        body: `▼ゼロから：同じ太さの柱でも、材料が強ければ細くできます。超高層建築物の下層階の柱は、普通のコンクリートでは太くなりすぎて部屋が使えなくなってしまいます。そこで強度の高いコンクリートを使うのですが、強くするということは水を減らして組織を緻密にすることであり、その代償として流動性が落ち、発熱が増え、火に弱くなります。高強度コンクリートは「強さと引き換えに何を失うか」を理解することが要点です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 高強度コンクリートの定義
━━━━━━━━━━━━━━━━━━━━━━
・JASS5では、設計基準強度が36N／mm2を超えるものを高強度コンクリートとする★
・土木学会示方書では、設計基準強度50N／mm2から100N／mm2程度を高強度として扱う★
・JIS A 5308のレディーミクストコンクリートの呼び強度の上限は60である★
・呼び強度60を超えるものは、JIS外の高強度コンクリートとして個別に品質を確認する
・建築では大臣認定を取得した高強度コンクリートが用いられる
・→ 建築36超、土木50以上、JISの上限60という三つの数値を区別する★

【図解】高強度コンクリートの区分
　基準｜高強度の範囲｜備考
　JASS5（建築）｜36N／mm2超★｜設計基準強度で区分
　土木学会示方書｜50から100N／mm2★｜それ以上は超高強度
　JIS A 5308｜呼び強度60が上限★｜これを超えるとJIS外
　⇒ 分野によって境界が違うことを理解しておく
　⚠ 「JISの呼び強度は80まである」は誤り。上限は60

━━━━━━━━━━━━━━━━━━━━━━
🔑 使用材料の選定
━━━━━━━━━━━━━━━━━━━━━━
・セメント：中庸熱・低熱ポルトランドセメント、シリカフュームプレミックスセメントなど★
・低熱ポルトランドセメントは、発熱抑制と長期強度の両面で高強度に適する★
・混和材：シリカフュームが代表的。微細な粒子が空隙を充填し、ポゾラン反応で界面を強化する★
・シリカフュームの置換率は10パーセント程度が一般的★
・混和剤：高性能AE減水剤が必須★。単位水量を大幅に減らしつつ流動性を確保する
・骨材：強度と弾性係数の高い硬質な骨材を選ぶ★。粗骨材が強度の頭打ちを決める場合がある
・粗骨材最大寸法は20mm以下、場合により13mmまで小さくする★

━━━━━━━━━━━━━━━━━━━━━━
🔑 シリカフュームの働き
━━━━━━━━━━━━━━━━━━━━━━
・平均粒径がセメントの100分の1程度と極めて細かい★
・マイクロフィラー効果：セメント粒子間の空隙を物理的に充填する★
・ポゾラン反応：水酸化カルシウムと反応してけい酸カルシウム水和物を生成し、遷移帯を強化する★
・骨材とペーストの界面（遷移帯）が強化されることが、高強度化の鍵である★
・比表面積が非常に大きいため単位水量が増える。高性能AE減水剤との併用が前提★
・材料分離が起こりにくくなり、粘性が高くなる★
・水和熱の低減効果は期待できない★

【図解】高強度化の材料的な手段
　手段｜効果｜代償
　水結合材比の低減｜組織の緻密化★｜流動性低下、発熱増
　シリカフューム｜遷移帯の強化★｜粘性増大、単位水量増
　硬質骨材の使用｜骨材強度の確保★｜入手性とコスト
　⇒ 高強度は「緻密化」と「界面強化」の二本柱
　⚠ シリカフュームで水和熱が下がるという記述は誤り

━━━━━━━━━━━━━━━━━━━━━━
🔑 高強度コンクリートの性質
━━━━━━━━━━━━━━━━━━━━━━
・ブリーディングがほとんど生じない★。表面が乾きやすくプラスチック収縮ひび割れに注意
・自己収縮が大きい★。水結合材比が小さいほど顕著で、ひび割れの原因になる
・粘性が高く、ポンプ圧送性が悪い★。管内圧力損失が大きくなる
・単位結合材量が多いため水和熱が大きく、部材が大きいと温度ひび割れが問題になる★
・ヤング係数は高いが、破壊は脆性的になる★。応力ひずみ曲線のピーク後の下降が急である
・中性化・塩化物イオン浸透に対する抵抗性は高い★
・火災時に爆裂を生じやすい★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「高強度コンクリートはブリーディングが多い」→×。ほとんど生じない★
・「自己収縮は水結合材比が大きいほど大きい」→×。小さいほど大きい★
・「高強度は靭性に富み延性的に破壊する」→×。脆性的★
・「シリカフュームは水和熱を低減する」→×
・「JISの呼び強度の上限は80」→×。60★

★ここだけ暗記
・JASS5は36N／mm2超、JISの呼び強度上限は60★
・シリカフュームはマイクロフィラー効果とポゾラン反応で遷移帯を強化★
・ブリーディングは極小、自己収縮は大★
・破壊は脆性的、火災で爆裂しやすい★`,
