        title: '繊維補強コンクリートと靭性',
        emoji: '🧵',
        body: `▼ゼロから：粘土だけで作った皿は落とすと粉々になりますが、細い繊維を混ぜておくと、ひびは入っても破片が飛び散りにくくなります。コンクリートは圧縮に強く引張に弱い材料で、ひび割れが入ると一気に耐力を失います。そこに短い繊維を混ぜておくと、ひび割れの両側を繊維が橋渡しし、割れた後も力を伝え続けます。粘り強さ、すなわち靭性が生まれるのです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 繊維補強の原理
━━━━━━━━━━━━━━━━━━━━━━
・繊維はひび割れをまたいで応力を伝達する（架橋作用・ブリッジング効果）★
・ひび割れ発生後も荷重を保持でき、荷重変位曲線の下降が緩やかになる★
・その結果、破壊エネルギー（靭性）が大きく向上する★
・引張強度や圧縮強度そのものは、大きくは向上しない★
・曲げ強度、せん断強度、耐衝撃性、疲労抵抗性は向上する★
・乾燥収縮ひび割れやプラスチック収縮ひび割れの抑制にも効果がある★
・→ 「強くする」のではなく「粘り強くする」のが繊維補強の本質★

【図解】繊維補強で向上する性能
　性能｜変化｜理由
　靭性（破壊エネルギー）｜大きく向上★｜ひび割れ後も応力を伝達
　曲げ靭性・耐衝撃性｜向上★｜架橋作用
　圧縮強度｜ほとんど変わらない★｜圧縮では架橋が効かない
　⇒ 「圧縮強度が大きく上がる」という記述は誤りである
　⚠ 繊維は鉄筋の代替ではない。主筋を省略する目的では使えない

━━━━━━━━━━━━━━━━━━━━━━
🔑 繊維の種類と特徴
━━━━━━━━━━━━━━━━━━━━━━
・鋼繊維：弾性係数と引張強度が高く、靭性向上効果が最も大きい★
・鋼繊維の混入率は体積比0.5から2.0パーセント程度★
・鋼繊維はアスペクト比（長さ÷直径）が40から100程度のものが用いられる★
・アスペクト比が大きいほど付着が有効になるが、ファイバーボールが生じやすい★
・合成繊維（ポリプロピレン、ビニロン、アラミド等）：軽く、さびず、化学的に安定★
・ポリプロピレン繊維は爆裂防止や初期ひび割れ抑制に用いられ、混入率は0.1から0.3パーセント程度★
・炭素繊維：高強度・高弾性だが高価。ガラス繊維：アルカリ耐性のあるものを用いる★

【図解】主な繊維の使い分け
　繊維｜主な目的｜混入率の目安
　鋼繊維｜靭性・曲げ強度の向上★｜0.5から2.0体積パーセント
　ポリプロピレン繊維｜爆裂防止・初期ひび割れ抑制★｜0.1から0.3体積パーセント
　ビニロン・アラミド繊維｜靭性向上、軽量・非腐食★｜1から2体積パーセント
　⇒ 鋼繊維は靭性、ポリプロピレンは爆裂と初期ひび割れ
　⚠ 目的が違う繊維を入れ替えた選択肢が頻出

━━━━━━━━━━━━━━━━━━━━━━
🔑 施工上の課題
━━━━━━━━━━━━━━━━━━━━━━
・繊維の混入によりワーカビリティが著しく低下する★。同じスランプを得るのに単位水量が増える
・繊維がからまって団子状になるファイバーボールが生じやすい★
・対策：分散しやすい形状の繊維を選ぶ、投入方法を工夫する、練混ぜ時間を長くする★
・単位粗骨材量を減らし、細骨材率を高めて繊維の分散を助ける★
・粗骨材最大寸法は繊維長より小さくする。一般に繊維長は粗骨材最大寸法の2倍以上とする★
・鋼繊維は表面に露出するとさびて美観を損ない、けがの原因にもなる★
・→ 「混ぜにくい」「分散しにくい」が最大の実務課題★

━━━━━━━━━━━━━━━━━━━━━━
🔑 靭性の評価
━━━━━━━━━━━━━━━━━━━━━━
・曲げ靭性試験により、荷重たわみ曲線の面積から曲げ靭性係数を求める★
・所定のたわみまでの吸収エネルギーを、たわみで除して等価な曲げ強度として表す
・繊維の混入率、アスペクト比、繊維の形状（端部フック等）が靭性に大きく影響する★
・繊維の方向がひび割れ面と直交するほど効果が高く、方向がそろうと性能が変わる★
・薄い部材では繊維が面内に配向し、実験値より性能が高く出ることがある

━━━━━━━━━━━━━━━━━━━━━━
🔑 適用例と頻出ひっかけ
━━━━━━━━━━━━━━━━━━━━━━
・適用例：トンネルの吹付けコンクリート、道路舗装、防爆構造物、二次製品、補修材★
・「鋼繊維の混入により圧縮強度が大幅に向上する」→×★
・「繊維補強すればワーカビリティが向上する」→×。低下する★
・「ポリプロピレン繊維は靭性向上が主目的」→×。爆裂防止と初期ひび割れ抑制★
・「鋼繊維の混入率は体積比10パーセント程度」→×。0.5から2.0パーセント★
・「アスペクト比は小さいほどファイバーボールが生じやすい」→×。大きいほど生じやすい★

★ここだけ暗記
・繊維補強の本質は靭性の向上、圧縮強度はほぼ不変★
・鋼繊維は0.5から2.0体積パーセント、アスペクト比40から100★
・ポリプロピレン繊維は0.1から0.3体積パーセントで爆裂防止★
・ファイバーボールとワーカビリティ低下が課題★`,
