━━━━━━━━━━━━━━━━━━━━━━
・打込み中はコンクリートの打上がり高さを検測し、理論打込み量と比較する★
・実打込み量が理論量を大きく上回る場合は孔壁の崩壊、下回る場合は充填不良を疑う★
・硬化後は超音波検層、コアボーリングにより健全性を確認することがある★
・杭頭のはつり後、目視で品質を確認する
・供試体は打込み口で採取するのが原則である

