        emoji: '🪣',
        body: `▼ゼロから：コップに大きめの氷を入れてから、後でジュースを注ぐと、氷のすき間がジュースで埋まります。プレパックドコンクリートはこれと同じ順序で作ります。先に粗骨材だけを型枠に詰めておき、後からモルタルを注入して骨材のすき間を埋めるのです。粗骨材どうしが直接接触しているので乾燥収縮が小さく、また既設構造物の周りや水中でも施工できるという特長があります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 プレパックドコンクリートとは
━━━━━━━━━━━━━━━━━━━━━━
・あらかじめ型枠内に粗骨材を投入して充填し、その空隙に注入モルタルを注入して造るコンクリートである★
・注入モルタルは下部から上部へ、注入管を通じて押し上げるように注入する★
・粗骨材が直接接触して骨格を形成するため、乾燥収縮とクリープが小さい★
・水中施工が可能で、既設構造物との一体化に優れる★
・大規模なものはプレパックドコンクリート、既設構造物の補修用はプレパックド工法として区別されることもある
・→ 「骨材を先に、モルタルを後から」の順序が最大の特徴★

━━━━━━━━━━━━━━━━━━━━━━
🔑 粗骨材の条件
━━━━━━━━━━━━━━━━━━━━━━
・粗骨材の最小寸法は15mm以上★とする
・粗骨材最大寸法は、部材の最小寸法の4分の1以下★、かつ鉄筋の最小あきの3分の2以下★とする
・粒度は単粒度に近いものが望ましく、空隙率が大きくモルタルが行き渡りやすい★
・粗骨材の最大寸法と最小寸法の比は、あまり大きくしない
・投入時に粒度分離を起こさないよう、投入方法に注意する★
・→ 「最小寸法15mm以上」は他の工法にない独特の条件★

【図解】プレパックド用粗骨材の寸法条件
　項目｜条件｜理由
　最小寸法｜15mm以上★｜モルタルが通る空隙を確保
　最大寸法｜部材最小寸法の4分の1以下★｜充填性の確保
　鉄筋との関係｜最小あきの3分の2以下★｜鉄筋間を通過させる
　⇒ 小さすぎる骨材はモルタルの通り道をふさぐので使えない
　⚠ 「最小寸法5mm以上」は誤り。15mm以上である

━━━━━━━━━━━━━━━━━━━━━━
🔑 注入モルタルの品質
━━━━━━━━━━━━━━━━━━━━━━
・高い流動性、材料分離抵抗性、適度な膨張性、低ブリーディングが要求される★
・流動性はPロート（漏斗）による流下時間で管理し、16秒から20秒程度★を目安とする
・ブリーディング率は3パーセント以下★とする
・膨張率は5パーセントから10パーセント程度★とし、空隙を確実に埋める
・アルミニウム粉末等の発泡系混和剤やプレパックド専用混和剤を用いる★
・フライアッシュを用いると流動性が向上し、材料分離が抑えられる★
・水セメント比は45パーセントから55パーセント程度とすることが多い

【図解】注入モルタルの管理項目
　項目｜基準｜目的
　Pロート流下時間｜16から20秒程度★｜適度な流動性
　ブリーディング率｜3パーセント以下★｜上面に水がたまらない
　膨張率｜5から10パーセント★｜空隙を確実に充填
　⇒ 流れやすく、分離せず、少し膨らむモルタルが理想
　⚠ 流下時間が短すぎると分離、長すぎると充填不良になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 注入の施工管理
━━━━━━━━━━━━━━━━━━━━━━
・注入管は型枠内にあらかじめ配置し、下端から注入する★
・注入管の間隔は、鉛直注入管で2m程度★とする
・注入管の先端は常にモルタル中に0.5m以上挿入した状態を保ちながら、徐々に引き上げる★
・注入は下から上へ、モルタル面を水平に保ちながら連続して行う★
・注入モルタル面の高さを検測孔で確認しながら施工する★
・注入中の中断は、コールドジョイントや未充填の原因になる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 特徴と適用
━━━━━━━━━━━━━━━━━━━━━━
・乾燥収縮が普通コンクリートの2分の1から3分の1程度と小さい★
・水中施工が可能で、水中でも材料分離しにくい★
・既設コンクリートとの付着がよく、補修・補強に適する★
・大断面の構造物、橋脚の増し厚、水中基礎、遮蔽コンクリートに用いられる★
・欠点：注入管の配置と管理に手間がかかる、強度の確認が難しい、施工実績が減少している
・→ 収縮が小さいことと水中施工性が二大長所★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「粗骨材の最小寸法は5mm以上」→×。15mm以上★
・「注入は上部から行う」→×。下部から押し上げる★
・「乾燥収縮は普通コンクリートより大きい」→×。小さい★
・「注入モルタルは収縮性のものを用いる」→×。膨張性★
・「ブリーディング率は10パーセント以下」→×。3パーセント以下★

★ここだけ暗記
・粗骨材の最小寸法15mm以上、最大寸法は部材最小寸法の4分の1以下★
・注入は下から上へ、注入管間隔2m程度★
・Pロート16から20秒、ブリーディング3パーセント以下、膨張率5から10パーセント★
・乾燥収縮が小さく水中施工が可能★`,
