        emoji: '🌊',
        body: `▼ゼロから：海辺に置いた自転車はすぐにさびます。塩分が金属をさびさせるからです。鉄筋コンクリートも同じで、海水の塩化物イオンがコンクリートの中を進んで鉄筋に達すると、鉄筋がさびて膨らみ、かぶりコンクリートを押し割ります。海の構造物は、この塩化物イオンとの競走に勝たなければなりません。守り方は二つ、「侵入を遅くする」ことと「鉄筋までの距離を長くする」ことです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 環境区分と劣化の激しさ
━━━━━━━━━━━━━━━━━━━━━━
・海洋環境は、海中部、干満帯・飛沫帯、海上大気中に区分される★
・最も劣化が激しいのは飛沫帯と干満帯である★
・理由は、乾湿の繰返しにより塩分が濃縮され、かつ酸素の供給が十分にあるため★
・海中部は常時水中にあり、酸素の供給が乏しいため腐食は比較的進みにくい★
・海上大気中は、飛来塩分の量により劣化の程度が変わる
・→ 「常に濡れている場所より、濡れたり乾いたりする場所が危ない」★

【図解】海洋環境の区分と厳しさ
　区分｜劣化の厳しさ｜理由
　飛沫帯・干満帯｜最も厳しい★｜乾湿繰返しで塩分濃縮、酸素も豊富
　海上大気中｜中程度｜飛来塩分の量による
　海中部｜比較的緩やか★｜酸素の供給が乏しい
　⇒ 飛沫帯が最悪、海中部が意外に穏やかという順序を押さえる
　⚠ 「常時海水中が最も厳しい」は誤り

━━━━━━━━━━━━━━━━━━━━━━
🔑 かぶりの確保
━━━━━━━━━━━━━━━━━━━━━━
・かぶりは塩化物イオンが鉄筋に到達するまでの時間を稼ぐ最も基本的な手段である★
・環境が厳しいほど大きなかぶりが必要になる★
・海上大気中では50mm程度、飛沫帯・干満帯では70mm程度★を目安とする例が多い
・かぶりが2倍になると、拡散による到達時間はおよそ4倍になる★
・スペーサを適切に配置し、施工中にかぶりが減らないよう管理する★
・→ 「侵入時間はかぶりの2乗に比例する」という関係が効果の根拠★

【図解】かぶりの目安
　環境｜かぶりの目安｜考え方
　海上大気中｜50mm程度★｜飛来塩分に対する備え
　飛沫帯・干満帯｜70mm程度★｜最も厳しい環境
　⇒ 厳しい環境ほど厚く。数値は目安として押さえる
　⚠ かぶり不足は現場の最大の欠陥要因。スペーサの数と配置を管理する

━━━━━━━━━━━━━━━━━━━━━━
🔑 配合による対策
━━━━━━━━━━━━━━━━━━━━━━
・水セメント比を小さくし、組織を緻密にして塩化物イオンの拡散を遅らせる★
・海洋環境では水セメント比45パーセントから50パーセント以下★とすることが多い
・高炉セメントB種・C種の使用が有効である★。塩化物イオンの拡散係数が小さい
・フライアッシュ、シリカフュームの使用も拡散抵抗性の向上に有効★
・単位水量を減らし、ブリーディングと空隙を減らす
・AE剤で凍結融解抵抗性も確保する
・→ 高炉セメントB種は塩害対策の第一選択である★

━━━━━━━━━━━━━━━━━━━━━━
🔑 施工上の対策
━━━━━━━━━━━━━━━━━━━━━━
・打継ぎ目は弱点になるため、干満帯や飛沫帯に設けない★
・打込み後、少なくとも5日間程度は海水に直接触れさせない★
・型枠は、コンクリートが所要の強度に達するまで存置する
・充填不良やジャンカは塩分の侵入経路になるため、締固めを確実に行う★
・鉄筋のかぶりを確保するスペーサは、コンクリート製または同等の耐久性のものとする★
・→ 「打継ぎ目を危険な高さに置かない」は必ず出る★

【図解】海洋コンクリートの対策のまとめ
　対策の方向｜具体策｜効果
　侵入を遅くする｜低W／C、高炉セメントB種★｜拡散係数の低減
　距離を稼ぐ｜かぶりの増大★｜到達時間はかぶりの2乗に比例
　欠陥をなくす｜締固め、打継ぎ位置★｜局所的な侵入経路を断つ
　⇒ 三方向から同時に手を打つのが基本設計
　⚠ 一つの対策だけで塩害を防ぐことはできない

━━━━━━━━━━━━━━━━━━━━━━
🔑 その他の防食手段
━━━━━━━━━━━━━━━━━━━━━━
・エポキシ樹脂塗装鉄筋の使用★。塗膜の損傷に注意が必要
・電気防食（流電陽極方式、外部電源方式）★
・表面被覆・表面含浸材による塩分侵入の遮断★
・ステンレス鉄筋、連続繊維補強材の使用
・防錆剤（亜硝酸塩系）の使用★
・コンクリート中の初期塩化物イオン量は0.30kg／m3以下★に管理する

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「海中部が最も腐食が激しい」→×。飛沫帯・干満帯★
・「普通ポルトランドセメントが塩害に最も強い」→×。高炉セメントB種等が有利★
・「打継ぎ目は干満帯に設けるとよい」→×★
・「初期塩化物イオン量の上限は3.0kg／m3」→×。0.30kg／m3★
・「かぶりを2倍にすると到達時間も2倍」→×。およそ4倍★

★ここだけ暗記
・最も厳しいのは飛沫帯・干満帯★
・かぶりは海上大気中50mm、飛沫帯・干満帯70mm程度★
・高炉セメントB種が有効、W／Cは45から50パーセント以下★
・打継ぎ目を干満帯・飛沫帯に設けない★`,
