・骨材の密度と含水状態を厳密に管理する
・打込み後の空隙・ジャンカの有無を、超音波や放射線透過で確認することがある★
・結合水量の確認のため、乾燥減量を測定することがある
・供試体は実構造物と同じ配合・締固め条件で作製する

