・鉄筋かごの位置がずれると、かぶり不足になる★
・排出されるノロの量と性状を管理し、配合の妥当性を確認する★
・脱型後は蒸気養生またはオートクレーブ養生により早期に強度を得る★

━━━━━━━━━━━━━━━━━━━━━━
