・骨材を事前に十分吸水させ、表面乾燥飽水状態に近づけてから使用する★
・吸水率の変動が大きいため、計量前に含水状態を頻繁に確認する★
・普通骨材と混合して使用し、影響を薄める方法もある★
・乾燥収縮対策として、膨張材や収縮低減剤を併用する★
・アルカリシリカ反応の可能性を、もとのコンクリートの履歴から検討する★
・塩化物イオン量を測定し、規定値以下であることを確認する★

