        id: 'cc-ka-49',
        title: '景観コンクリートと化粧打放し',
        emoji: '🎨',
        body: `▼ゼロから：仕上げ材で覆ってしまうなら表面の多少の傷は問題になりませんが、コンクリートの肌をそのまま見せる打放し仕上げでは、気泡ひとつ、色むらひとつが作品の出来を左右します。しかもコンクリートは一度打ってしまえばやり直しがききません。景観コンクリートは、材料・型枠・打込み・養生のすべてを「見せる」前提で組み立て直す仕事です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 打放し仕上げの要求
━━━━━━━━━━━━━━━━━━━━━━
・型枠を外したままの面を仕上げ面とするため、表面の平坦さ、色調の均一さ、気泡の少なさが求められる★
・セパレータ跡、型枠の継目、打継ぎ目の位置も意匠として計画する★
・ジャンカ、コールドジョイント、砂すじ、色むらは補修しても目立つ★
・補修跡が目立たないよう、補修材の色調と施工方法を事前に検討する★
・→ 「補修できない前提で作る」のが打放しの心構え★

━━━━━━━━━━━━━━━━━━━━━━
🔑 材料と配合
━━━━━━━━━━━━━━━━━━━━━━
・セメント・骨材は同一の産地・銘柄のものを工事期間中通して使用する★
・産地が変わると色調が変わり、部位ごとに色むらが生じる★
・単位水量を少なくし、ブリーディングと砂すじを抑える★
・細骨材率をやや高めにし、粘性を確保して気泡の抜けと表面の緻密さを両立させる★
・高性能AE減水剤により、低水量でも良好なワーカビリティを得る★
・高流動コンクリートを用いると、締固めによるむらがなく美しい表面が得られる★
・混和材の種類・量を変えると色調が変わるため、途中で変更しない★

【図解】色むらの主な原因
　原因｜内容｜対策
　材料の変更｜セメント・骨材の産地変更★｜工事期間中は統一する
　はく離剤｜塗りむら、過剰塗布★｜薄く均一に塗る
　脱型時期の差｜部位ごとの養生条件の違い★｜脱型時期をそろえる
　⇒ 色むらは材料・型枠・養生の三方向から発生する
　⚠ 「色むらは補修塗装で簡単に消せる」は誤り。塗装は打放しの意匠を失わせる

━━━━━━━━━━━━━━━━━━━━━━
🔑 型枠とはく離剤
━━━━━━━━━━━━━━━━━━━━━━
・せき板は塗装合板、樹脂加工合板、鋼製型枠など、要求する肌に応じて選定する★
・型枠の剛性を高め、はらみや目違いを防ぐ★
・型枠の継目にはシールを施し、ペーストの漏れによる砂すじを防ぐ★
・はく離剤は薄く均一に塗布する。過剰塗布は色むらと表面の粉状化を招く★
・透水型枠（透水性のシートを内貼りした型枠）を用いると、表面の余剰水と気泡が排出される★
・透水型枠により、表層の水セメント比が下がり、緻密で気泡の少ない美しい面が得られる★
・→ 透水型枠は「見た目」と「耐久性」を同時に改善する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 打込みと締固め
━━━━━━━━━━━━━━━━━━━━━━
・打込み速度を一定に保ち、打重ね時間を管理する★
・バイブレータは型枠に接触させず、同じ位置に挿入間隔をそろえて用いる★
・型枠をたたく（木づちによる打撃）、型枠バイブレータを併用して気泡を抜く★
・打上がり面の高さを一定に保ち、打継ぎ目の位置を意匠に合わせる★
・打込み高さを高くしすぎると、材料分離と色むらの原因になる★

【図解】表面欠陥と原因
　欠陥｜主な原因｜対策
　気泡（あばた）｜締固め不足、はく離剤過多★｜締固めの徹底、透水型枠
　砂すじ｜ブリーディング、型枠からの漏れ★｜単位水量低減、継目のシール
　色むら｜材料変更、脱型時期の差★｜材料統一、脱型時期をそろえる
　⇒ 欠陥の種類ごとに原因が異なるので、対策も分けて考える
　⚠ 気泡は締固めを強くすればよいというものではなく、抜け道を作ることが重要

━━━━━━━━━━━━━━━━━━━━━━
🔑 意匠のバリエーション
━━━━━━━━━━━━━━━━━━━━━━
・洗い出し仕上げ：表面の未硬化のペーストを洗い流し、骨材を露出させる★
・研磨仕上げ：硬化後に表面を研磨し、骨材の断面を見せる★
・型枠の内側に模様型を貼り付ける化粧型枠（テクスチャ型枠）★
・着色コンクリート：無機顔料を用いる。有機顔料はアルカリや紫外線に弱い★
・目地棒、面木により陰影を作り、色むらを目立たせない意匠とする★
・表面保護材（撥水材、含浸材）で汚れの付着とエフロレッセンスを抑える★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「はく離剤は多めに塗ると仕上がりがよい」→×★
・「透水型枠は表面の水セメント比を上げる」→×。下げる★
・「着色には有機顔料を用いる」→×。無機顔料★
・「途中で骨材の産地が変わっても色調に影響しない」→×★
・「バイブレータは型枠に直接当てて振動を伝える」→×。型枠バイブレータを使う★

★ここだけ暗記
・材料は工事期間中統一、はく離剤は薄く均一★
・透水型枠は表層のW／Cを下げ、気泡を減らす★
・欠陥は気泡・砂すじ・色むらの三つで整理★
・着色は無機顔料★`,
